#pragma once
#include <cstddef>
#include <cstdint>

// Network schema of item data components, generated by
// tools/compile_components.py into component_schema.cpp. Nodes are ProtoDef
// type expressions; see components.cpp for their meaning.
namespace circuit::protocol::detail {

enum class SchemaOp : std::uint8_t {
    void_, boolean_, i8_, u8_, i16_, u16_, i32_, i64_, f32_, f64_, varint_, varlong_, string_, uuid_, position_,
    nbt_, optional_nbt_, option_, array_, container_, switch_, mapper_, bitfield_, holder_, holder_set_, slot_,
    component_, buffer_, ref_,
};

// a, b, c, d by op:
//   option: a = value node; ref: a = node;
//   array: a = element node, b = name of the field holding the count (0: VarInt prefix),
//          c = 1 when the list is a map or set whose canonical order is sorted;
//   container: a = first field, b = field count;
//   switch: a = name of the compared field, b = first case, c = case count, d = default node + 1 (0: none);
//   mapper: a = first mapping, b = mapping count; bitfield: a = first bit field, b = count;
//   holder: a = inline value node.
// `registry` names the registry or enumeration a varint, holder or holder set refers to (0: none).
struct SchemaNode {
    SchemaOp op;
    std::uint32_t registry;
    std::uint32_t a, b, c, d;
};
struct SchemaField {
    std::uint32_t name;
    std::uint32_t node;
    std::uint8_t anon;
};
struct SchemaCase {
    std::uint32_t value;
    std::uint32_t node;
};
struct SchemaMapping {
    std::int32_t key;
    std::uint32_t value;
};
struct SchemaBit {
    std::uint32_t name;
    std::uint8_t size;
    std::uint8_t is_signed;
};
struct SchemaComponent {
    std::uint32_t name;
    std::uint32_t node;
};
struct SchemaRegistrySize {
    std::uint32_t name;
    std::uint32_t size;
};
struct ComponentSchema {
    std::int32_t protocol;
    const SchemaNode* nodes;
    const SchemaField* fields;
    const SchemaCase* cases;
    const SchemaMapping* mappings;
    const SchemaBit* bits;
    const SchemaComponent* components;
    std::size_t component_count;
    const SchemaRegistrySize* sizes;
    std::size_t size_count;
};

const char* schema_string(std::uint32_t index) noexcept;
const ComponentSchema* component_schema(std::int32_t protocol) noexcept;

} // namespace circuit::protocol::detail
